(5, 68, 'ข้อเสนอแนะเรื่องการค้นหารายวิชา', 'ลองใช้งานมาสักพักแล้ว อยากให้ค้นหาจากชื่ออาจารย์ได้ด้วย จะช่วยหารายวิชาที่ต้องการได้เร็วขึ้น', 'resolved', '2026-09-08 22:15:29'),
(6, 85, 'แจ้งปัญหาการแสดงผลบนหน้าจอ', 'บนจอเล็กตารางค่อนข้างกว้าง ถ้าทำให้เลื่อนในกรอบได้จะใช้งานสะดวกขึ้นครับ', 'resolved', '2026-07-10 22:15:29'),
